'use strict';

var Linter = require( 'eslint' ).Linter;
var rule = require( './../lib' );

var linter = new Linter();
var result;

var code = [
	'/**',
	'* Comparator function for sorting characters in ascending order.',
	'*',
	'* @param {string} a - character',
	'* @param {string} b - character',
	'* @returns {number} comparison value',
	'*/',
	'function ascending( a, b ) {',
	'  if ( a < b ) {',
	'    return -1;',
	'  }',
	'  if ( a === b ) {',
	'    return 0;',
	'  }',
	'  return 1;',
	'}',
	'',
	'var arr = [ 3, 1, 6, 12, 9, 2 ];',
	'',
	'module.exports = arr.sort( ascending );'
].join( '\n' );

result = linter.verify( code, {
	'plugins': {
		'stdlib': {
			'rules': {
				'jsdoc-private-annotation': rule
			}
		}
	},
	'rules': {
		'stdlib/jsdoc-private-annotation': [ 'error' ]
	}
});
console.log( result );
